const clamp = value => Math.min(1, Math.max(0, value));
const smooth = (start, end, value) => {
  const progress = clamp((value - start) / (end - start));
  return progress * progress * (3 - 2 * progress);
};
const progress = clamp(frame / Math.max(1, durationFrames - 1));
const color = /^#[0-9a-f]{6}$/i.test(props.color) ? props.color : '#ffd18a';
const glow = Number.isFinite(props.glow) ? Math.max(0, props.glow) : 1;
const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('"', '&quot;').replaceAll('<', '&lt;');
const artwork = escape(assets.artwork);
const outline = escape(assets.outline);
const border = clamp((progress - 0.035) / 0.51);
const baseLines = 0.24 * smooth(0, 0.12, progress);
const colorOpacity = smooth(0.65, 0.9, progress);
const lineOpacity = (1 - smooth(0.78, 0.95, progress)) * smooth(0, 0.045, progress);
const borderY = height * border;
const blur = width / 320;
const image = (source, attributes = '') => '<image href="' + source + '" width="' + width + '" height="' + height + '" preserveAspectRatio="none" ' + attributes + '/>';
return '<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="0 0 ' + width + ' ' + height + '" role="img" aria-label="图片金线显影">' +
  '<defs>' +
    '<filter id="gold" x="-20%" y="-20%" width="140%" height="140%" color-interpolation-filters="sRGB">' +
      '<feFlood flood-color="' + color + '"/><feComposite in2="SourceAlpha" operator="in" result="ink"/>' +
      '<feGaussianBlur in="ink" stdDeviation="' + blur + '"/><feComponentTransfer result="soft"><feFuncA type="linear" slope="' + glow + '"/></feComponentTransfer>' +
      '<feGaussianBlur in="ink" stdDeviation="' + (width / 70) + '"/><feComponentTransfer result="bloom"><feFuncA type="linear" slope="' + glow + '"/></feComponentTransfer>' +
      '<feMerge><feMergeNode in="ink"/><feMergeNode in="soft"/><feMergeNode in="bloom"/></feMerge>' +
    '</filter>' +
    '<linearGradient id="reveal" gradientUnits="userSpaceOnUse" x1="0" y1="' + (borderY - height * 0.08) + '" x2="0" y2="' + (borderY + height * 0.1) + '"><stop stop-color="white"/><stop offset="1" stop-color="black"/></linearGradient>' +
    '<mask id="travel" maskUnits="userSpaceOnUse"><rect width="' + width + '" height="' + height + '" fill="url(#reveal)"/></mask>' +
    '<radialGradient id="spark"><stop stop-color="' + color + '" stop-opacity="1"/><stop offset="1" stop-color="' + color + '" stop-opacity="0"/></radialGradient>' +
  '</defs>' +
  '<rect width="' + width + '" height="' + height + '" fill="black"/>' +
  '<g opacity="' + (0.085 * smooth(0, 0.15, progress) * (1 - colorOpacity)) + '">' + image(artwork) + '</g>' +
  '<g data-golden-color="1" opacity="' + colorOpacity + '">' + image(artwork) + '</g>' +
  '<g data-golden-lines="1" opacity="' + lineOpacity + '" filter="url(#gold)">' +
    '<g opacity="' + baseLines + '">' + image(outline) + '</g>' +
    '<g mask="url(#travel)">' + image(outline) + '</g>' +
  '</g>' +
  '<ellipse cx="' + width * 0.5 + '" cy="' + height * 0.02 + '" rx="' + width * 0.07 + '" ry="' + height * 0.04 + '" fill="url(#spark)" opacity="' + smooth(0, 0.04, progress) * (1 - smooth(0.12, 0.24, progress)) * glow + '"/>' +
  '</svg>';
